 const beginSession=async(req,res,name)=>{if(req.session.sid)await redis.del('sid:'+req.session.sid);return newSession(res,req.secure,name);};
 const tx=async(handler,rollbackRejected=false)=>{const c=await db.connect();try{await c.query('BEGIN');const result=await handler(c);await c.query(rollbackRejected&&result?.status>=400?'ROLLBACK':'COMMIT');return result;}catch(error){await c.query('ROLLBACK');throw error;}finally{c.release();}};
