 post('/b2-account/recover',['R0207','R0211','R0218'],async(req,res)=>{const name=String(req.body.username||''),a=await account(name);if(a?.active){let publicValue,value;if(getRun().root==='R0211'){await db.query("DELETE FROM wf2_tokens WHERE owner=$1 AND kind='recovery'",[name]);publicValue=vulnerable()?String(randomInt(4)).padStart(2,'0'):token();value=await issue('recovery',name,{generation:a.generation},Date.now()+ttl,name+':'+publicValue);}else{value=await issue('recovery',name,{generation:a.generation});publicValue=value;}const origin=getRun().root==='R0207'&&vulnerable()?req.protocol+'://'+req.headers.host:'https://app:8443';await mail(name,publicValue,'recovery',{url:origin+getRun().base+'/b2-account/reset?token='+encodeURIComponent(publicValue)});}res.json({message:'If the account exists, a message has been sent.'});});
 post('/b2-account/reset',['R0207','R0211','R0218'],async(req,res)=>{const root=getRun().root,name=String(req.body.username||''),password=req.body.password;if(typeof password!=='string'||password.length<16||password.length>128)return res.sendStatus(400);if(root==='R0211'){if(!['alice','bob','carol'].includes(name))return res.sendStatus(400);const k='wf2-budget:recovery:'+name;if(await redis.incr(k)>4)return res.sendStatus(429);await redis.expire(k,600);}const submitted=String(req.body.token||''),lookup=root==='R0211'?name+':'+submitted:submitted;const result=await tx(async c=>{const row=(await c.query("SELECT * FROM wf2_tokens WHERE value=$1 AND kind='recovery' FOR UPDATE",[lookup])).rows[0];if(!row||row.used||row.revoked||Date.parse(row.expires_at)<=Date.now()||(root==='R0211'&&row.owner!==name))return false;const a=(await c.query('SELECT * FROM wf2_accounts WHERE username=$1 FOR UPDATE',[row.owner])).rows[0];if(!a?.active||(root==='R0218'&&!vulnerable()&&row.data.generation!==a.generation))return false;await c.query('UPDATE users SET password=$1 WHERE name=$2',[password,row.owner]);await c.query('UPDATE wf2_accounts SET password=$1 WHERE username=$2',[password,row.owner]);await c.query('UPDATE wf2_tokens SET used=true WHERE value=$1',[row.value]);await event(c,row.owner,'recovery-completed');return true;});res.sendStatus(result?200:400);});
 post('/b2-account/close',['R0218'],async(req,res)=>{if(!requireLogin(req,res))return;if(req.member.name!=='alice')return res.sendStatus(403);await tx(async c=>{await c.query("UPDATE wf2_accounts SET active=false WHERE username='alice'");await c.query("DELETE FROM users WHERE name='alice'");await event(c,'alice','account-closed');});if(req.session.sid)await redis.del('sid:'+req.session.sid);res.clearCookie('sid',{path:'/'});res.json({closed:true});});
 post('/b2-account/rejoin',['R0218'],async(req,res)=>{if(req.body.username!=='alice'||typeof req.body.password!=='string'||req.body.password.length<16||req.body.password.length>128)return res.sendStatus(400);const done=await tx(async c=>{const a=(await c.query("SELECT * FROM wf2_accounts WHERE username='alice' FOR UPDATE")).rows[0];if(a.active)return false;await c.query("UPDATE wf2_accounts SET active=true,password=$1,generation=$2 WHERE username='alice'",[req.body.password,token()]);await c.query("INSERT INTO users(name,password,role,tenant,contact,balance) VALUES('alice',$1,'user','A','alice@example.test',3000)",[req.body.password]);return true;});res.sendStatus(done?201:409);});
 post('/b2-security/remember',['R0230'],async(req,res)=>{if(!requireLogin(req,res))return;res.json({token:await issue('remember',req.member.name),expiresAt:new Date(Date.now()+ttl).toISOString()});});
 get('/b2-security/remember-history',['R0230'],async(req,res)=>{if(!requireLogin(req,res))return;if(await redis.incr('wf2-history:'+req.member.name)>4)return res.sendStatus(429);const expired=await issue('remember',req.member.name,{},Date.now()-60000);res.json({ownExpiredToken:expired,expiredAt:new Date(Date.now()-60000).toISOString()});});
